PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
PRAGMA synchronous=FULL;
PRAGMA busy_timeout=5000;
CREATE TABLE IF NOT EXISTS metadata(key TEXT PRIMARY KEY,value BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tenants(environment TEXT NOT NULL, tenant_id TEXT NOT NULL, quota TEXT NOT NULL CHECK(json_valid(quota)), PRIMARY KEY(environment,tenant_id));
CREATE TABLE IF NOT EXISTS credentials(id TEXT PRIMARY KEY, environment TEXT NOT NULL, tenant_id TEXT NOT NULL, hash BLOB NOT NULL UNIQUE, scopes TEXT NOT NULL, expires_at TEXT NOT NULL, revoked INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(environment,tenant_id) REFERENCES tenants(environment,tenant_id));
CREATE TABLE IF NOT EXISTS cameras(id TEXT NOT NULL, environment TEXT NOT NULL, tenant_id TEXT NOT NULL, code TEXT NOT NULL, enabled INTEGER NOT NULL, revision INTEGER NOT NULL, source BLOB NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), PRIMARY KEY(environment,tenant_id,id), UNIQUE(environment,tenant_id,code), FOREIGN KEY(environment,tenant_id) REFERENCES tenants(environment,tenant_id));
CREATE TABLE IF NOT EXISTS operations(id TEXT NOT NULL, environment TEXT NOT NULL, tenant_id TEXT NOT NULL, key TEXT NOT NULL, digest TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), PRIMARY KEY(environment,tenant_id,id), UNIQUE(environment,tenant_id,key), FOREIGN KEY(environment,tenant_id) REFERENCES tenants(environment,tenant_id));
CREATE TABLE IF NOT EXISTS executions(id TEXT NOT NULL, environment TEXT NOT NULL, tenant_id TEXT NOT NULL, camera_id TEXT NOT NULL, state TEXT NOT NULL, desired TEXT NOT NULL, generation TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), PRIMARY KEY(environment,tenant_id,id), FOREIGN KEY(environment,tenant_id,camera_id) REFERENCES cameras(environment,tenant_id,id));
CREATE UNIQUE INDEX IF NOT EXISTS one_camera_producer ON executions(environment,tenant_id,camera_id) WHERE state IN ('queued','preparing','running','stopping');
CREATE INDEX IF NOT EXISTS execution_queue ON executions(state,environment,tenant_id);
CREATE TABLE IF NOT EXISTS reservations(environment TEXT NOT NULL, tenant_id TEXT NOT NULL, execution_id TEXT NOT NULL, memory_mib INTEGER NOT NULL CHECK(memory_mib>=0), state TEXT NOT NULL, PRIMARY KEY(environment,tenant_id,execution_id), FOREIGN KEY(environment,tenant_id,execution_id) REFERENCES executions(environment,tenant_id,id));
CREATE TABLE IF NOT EXISTS workers(id TEXT PRIMARY KEY, environment TEXT NOT NULL, tenant_id TEXT NOT NULL, execution_id TEXT NOT NULL, controller_id TEXT NOT NULL, pid INTEGER NOT NULL, state TEXT NOT NULL, FOREIGN KEY(environment,tenant_id,execution_id) REFERENCES executions(environment,tenant_id,id));
CREATE TABLE IF NOT EXISTS events(sequence INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL, environment TEXT NOT NULL, tenant_id TEXT NOT NULL, execution_id TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), UNIQUE(environment,tenant_id,id), FOREIGN KEY(environment,tenant_id,execution_id) REFERENCES executions(environment,tenant_id,id));
CREATE INDEX IF NOT EXISTS event_scope ON events(environment,tenant_id,sequence);
CREATE TABLE IF NOT EXISTS destinations(environment TEXT NOT NULL,tenant_id TEXT NOT NULL,revision INTEGER NOT NULL,url TEXT NOT NULL,token BLOB NOT NULL,PRIMARY KEY(environment,tenant_id,revision),FOREIGN KEY(environment,tenant_id) REFERENCES tenants(environment,tenant_id));
CREATE TABLE IF NOT EXISTS deliveries(id TEXT PRIMARY KEY,environment TEXT NOT NULL,tenant_id TEXT NOT NULL,event_id TEXT NOT NULL,destination_revision INTEGER NOT NULL,state TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,next_at TEXT NOT NULL,last_status INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(environment,tenant_id,event_id) REFERENCES events(environment,tenant_id,id),FOREIGN KEY(environment,tenant_id,destination_revision) REFERENCES destinations(environment,tenant_id,revision));
CREATE TABLE IF NOT EXISTS delivery_attempts(delivery_id TEXT NOT NULL,attempt INTEGER NOT NULL,status INTEGER NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(delivery_id,attempt),FOREIGN KEY(delivery_id) REFERENCES deliveries(id));
CREATE TABLE IF NOT EXISTS retention(environment TEXT NOT NULL,tenant_id TEXT NOT NULL,floor INTEGER NOT NULL,PRIMARY KEY(environment,tenant_id),FOREIGN KEY(environment,tenant_id) REFERENCES tenants(environment,tenant_id));
CREATE INDEX IF NOT EXISTS delivery_due ON deliveries(state,next_at);
CREATE TABLE IF NOT EXISTS schedules(id TEXT NOT NULL,environment TEXT NOT NULL,tenant_id TEXT NOT NULL,camera_id TEXT NOT NULL,data TEXT NOT NULL CHECK(json_valid(data)),PRIMARY KEY(environment,tenant_id,id),FOREIGN KEY(environment,tenant_id,camera_id) REFERENCES cameras(environment,tenant_id,id));
CREATE TABLE IF NOT EXISTS occurrences(environment TEXT NOT NULL,tenant_id TEXT NOT NULL,schedule_id TEXT NOT NULL,occurrence TEXT NOT NULL,outcome TEXT NOT NULL,PRIMARY KEY(environment,tenant_id,schedule_id,occurrence),FOREIGN KEY(environment,tenant_id,schedule_id) REFERENCES schedules(environment,tenant_id,id));
CREATE TABLE IF NOT EXISTS execution_media(environment TEXT NOT NULL,tenant_id TEXT NOT NULL,execution_id TEXT NOT NULL,media BLOB NOT NULL,PRIMARY KEY(environment,tenant_id,execution_id),FOREIGN KEY(environment,tenant_id,execution_id) REFERENCES executions(environment,tenant_id,id));
CREATE TABLE IF NOT EXISTS audit(sequence INTEGER PRIMARY KEY AUTOINCREMENT,environment TEXT NOT NULL,tenant_id TEXT NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,resource TEXT NOT NULL,request_id TEXT NOT NULL,result TEXT NOT NULL,created_at TEXT NOT NULL);
INSERT OR IGNORE INTO migrations VALUES(1,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
